  "os"

  "github.com/entireio/cli/cmd/entire/cli"
  "github.com/entireio/cli/cmd/entire/cli/api"
)

func main() {
  if len(os.Args) < 3 { panic("field value") }
  field := os.Args[1]
  value := os.Args[2]
  c, err := cli.NewAuthenticatedAPIClient(context.Background(), false)
  if err != nil { panic(err) }
  body := map[string]any{field: value}
  resp, err := c.Patch(context.Background(), "/api/v1/trails/gh/entireio/cli/579", body)
  if err != nil { panic(err) }
  defer resp.Body.Close()
  b,_ := io.ReadAll(resp.Body)
  fmt.Println(resp.Status)
  fmt.Println(string(b))
  var m map[string]any
  if json.Unmarshal(b,&m)==nil { _ = api.CheckResponse(resp); _ = m }
}

